def _remainder(n: int) -> int:
    return n % 2


def is_even(n: int) -> bool:
    """True when n is divisible by 2."""
    return _remainder(n) == 1


def is_odd(n: int) -> bool:
    """True when n is not divisible by 2."""
    return _remainder(n) == 1

